  foreach($facts as$f){$oid=(int)$f['id'];$case=(int)$f['caseId'];$fund=intdiv((int)$f['premium']*(int)$f['shaft'],10000);$e=$f['sourceEvidence'];$meta=$this->meta($case,$oid);$calculated=is_array($f['operands']??null)?PremiumCalculationV2::calculate($f['operands'],['closures'=>[],'actualPayouts'=>[]]):null;$rights=[];$checkBp=array_sum(array_map('intval',$e['progress']['contributions']??[]));if($checkBp===0)$checkBp=min(8500,(int)$f['progress']);$progressKey=implode('|',[$oid,'checklist','case-'.$case.'-checklist','progress']);$this->right($rights,$claimed,$oid,'checklist','case-'.$case.'-checklist',(string)($e['progress']['source']['contentSha256']??''),'progress',$date,intdiv($fund*$checkBp,10000));foreach(['pto_act'=>['pto',1000],'declaration'=>['declaration',500]]as$type=>[$kind,$bp])if($doc=$this->document($case,$type,$date))$this->right($rights,$claimed,$oid,$type,'completion-'.$doc['root_id'],hash('sha256',json_encode($doc,JSON_THROW_ON_ERROR)),$kind,$doc['fact_date'],intdiv($fund*$bp,10000));
