 private function frontier(string$key):int{return(int)$this->db->createCommand("SELECT claimed_cents FROM `{$this->prefix}fm2_otiz_entitlement_frontiers` WHERE right_key=:key",[':key'=>$key])->queryScalar();}
 private function replacementRecipients(array$current,array$old):array{if(($current['recipients']??[])!==[])return$current['recipients'];return$old['recipients']??[];}
 private function claimState():array{$rows=$this->db->createCommand("SELECT c.object_id,c.source_kind,c.source_id,c.source_revision,c.entitlement_kind,c.gross_cents,r.input_json FROM `{$this->prefix}fm2_otiz_entitlement_claims` c JOIN `{$this->prefix}fm2_otiz_calculation_revisions` r ON r.id=c.calculation_id WHERE c.active=1 ORDER BY c.id")->queryAll();$out=[];foreach($rows as$row){$key=implode('|',[(int)$row['object_id'],$row['source_kind'],$row['source_id'],$row['entitlement_kind']]);$out[$key]['gross']=($out[$key]['gross']??0)+(int)$row['gross_cents'];$out[$key]['sourceRevision']=(string)$row['source_revision'];$input=json_decode((string)$row['input_json'],true);foreach($input['objects']??[]as$object)if((int)$object['objectId']===(int)$row['object_id']){$contributions=$object['sourceEvidence']['progress']['contributions']??null;if(is_array($contributions))$out[$key]['contributions']=array_map('intval',$contributions);break;}}return$out;}
 private function right(array&$out,array$claimed,int$o,string$sourceKind,string$sourceId,string$revision,string$kind,string$date,int$cumulative):void{$rightKey=implode('|',[$o,$sourceKind,$sourceId,$kind]);$prior=(int)($claimed[$rightKey]['gross']??0);$delta=max(0,$cumulative-$prior);if($delta>0)$out[]=['rightKey'=>$rightKey,'sourceKind'=>$sourceKind,'sourceId'=>$sourceId,'sourceRevision'=>$revision,'kind'=>$kind,'recognitionDate'=>$date,'baselineClaimedCents'=>$prior,'cumulativeGrossCents'=>$cumulative,'grossCents'=>$delta];}
 private function latestProgressRecipients(int$case,string$date):array{$received=substr(($this->clock)(),0,10);$operation=$this->db->createCommand("SELECT client_operation_id FROM `{$this->prefix}fm2_checklist_operations` WHERE installation_case_id=:case AND operation_type='item_completed' AND LEFT(device_time,10)<=:date AND LEFT(server_received_at,10)<=:received ORDER BY accepted_revision DESC,id DESC LIMIT 1",[':case'=>$case,':date'=>$date,':received'=>$received])->queryScalar();if(!is_string($operation))return[];return array_map('strval',$this->db->createCommand("SELECT installer_tab_id FROM `{$this->prefix}fm2_checklist_operation_installers` WHERE client_operation_id=:id ORDER BY installer_tab_id",[':id'=>$operation])->queryColumn());}
 private function documentaryKss(int$objectId,mixed$current):?int{$rows=$this->db->createCommand("SELECT projection_json FROM `{$this->prefix}fm2_otiz_calculation_revisions` WHERE status='accepted' ORDER BY id")->queryColumn();$values=[];foreach($rows as$json)foreach((json_decode((string)$json,true)['objects']??[])as$object)if((int)($object['objectId']??0)===$objectId&&isset($object['kssBp']))$values[]=(int)$object['kssBp'];if($current!==null)$values[]=(int)$current;return$values===[]?null:min($values);}
